//! MITRE's official name, description and potential mitigations for every CWE the scanner
//! can report, built into the binary so findings are explained without anything written by
//! hand. Only the scanner's own CWEs are kept: a finding with any other number (one a
//! program reported, say) is shown by its number alone.
//!
//! The data is `assets/cwe/catalog.json`, generated by `tools/update_cwe.py` from the CWE
//! numbers in `scan::ALL_CHECKS`. Adding a check with a new CWE means running that script
//! again; `every_scanner_check_is_explained_by_mitre` fails until it is.
//! CWE content is Copyright (c) The MITRE Corporation, used under the CWE Terms of Use in
//! `assets/cwe/LICENSE`.

use std::sync::OnceLock;

const RAW: &str = include_str!("../assets/cwe/catalog.json");

#[derive(Debug, serde::Deserialize)]
pub struct Weakness {
    pub id: u32,
    pub name: String,
    pub description: String,
    #[serde(default)]
    pub mitigations: Vec<String>,
}

#[derive(serde::Deserialize)]
struct Catalog {
    version: String,
    weaknesses: Vec<Weakness>,
}

fn catalog() -> &'static Catalog {
    static CATALOG: OnceLock<Catalog> = OnceLock::new();
    CATALOG.get_or_init(|| {
        let mut c: Catalog = serde_json::from_str(RAW).unwrap_or(Catalog { version: String::new(), weaknesses: Vec::new() });
        c.weaknesses.sort_by_key(|w| w.id);
        c
    })
}

/// The CWE list version built in, such as "4.14".
pub fn version() -> &'static str {
    &catalog().version
}

/// MITRE's entry for a CWE number, if it names a current weakness.
pub fn lookup(cwe: u32) -> Option<&'static Weakness> {
    let all = &catalog().weaknesses;
    all.binary_search_by_key(&cwe, |w| w.id).ok().map(|i| &all[i])
}

/// "CWE-614: Sensitive Cookie in HTTPS Session Without 'Secure' Attribute", or just the
/// number for one the catalogue does not know.
pub fn title(cwe: u32) -> String {
    match lookup(cwe) {
        Some(w) => format!("CWE-{}: {}", w.id, w.name),
        None => crate::scan::cwe_label(cwe),
    }
}

/// The mitigations as one block of text, one per paragraph.
pub fn remediation(cwe: u32) -> Option<String> {
    lookup(cwe).filter(|w| !w.mitigations.is_empty()).map(|w| w.mitigations.join("\n\n"))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::scan;

    #[test]
    fn the_built_in_list_loads() {
        assert!(!version().is_empty(), "the catalogue names its CWE version");
        assert!(!catalog().weaknesses.is_empty());
    }

    #[test]
    fn every_scanner_check_is_explained_by_mitre() {
        for (cwe, name, _) in scan::ALL_CHECKS {
            let w = lookup(*cwe).unwrap_or_else(|| {
                panic!("'{name}' uses CWE-{cwe}, which assets/cwe/catalog.json lacks: run python3 tools/update_cwe.py")
            });
            assert!(!w.description.is_empty(), "CWE-{cwe} has a description");
        }
    }

    #[test]
    fn the_catalogue_holds_only_what_the_scanner_reports() {
        for w in &catalog().weaknesses {
            assert!(
                scan::ALL_CHECKS.iter().any(|(cwe, _, _)| *cwe == w.id),
                "CWE-{} is in the catalogue but no check reports it: run python3 tools/update_cwe.py",
                w.id
            );
        }
        let w = lookup(scan::SQL_INJECTION.0).expect("SQL injection is explained");
        assert!(w.name.contains("SQL Injection"), "{}", w.name);
        assert!(title(scan::SQL_INJECTION.0).starts_with("CWE-89: "));
        assert!(remediation(scan::SQL_INJECTION.0).is_some());
    }

    #[test]
    fn unknown_and_missing_cwes_fall_back_to_the_number() {
        assert!(lookup(scan::NO_CWE).is_none());
        assert_eq!(title(scan::NO_CWE), "No CWE");
        assert_eq!(title(79), "CWE-79", "a CWE no check reports is shown by its number");
    }
}
